    19	 * The bulk changes are let through: a viewer's bulk change is answered with every selected claim
    20	 * refused (see {@code BulkChangeService}), a viewer's bulk grade with no one changed (see
    21	 * {@code BulkGradeService}), a viewer's bulk retire with no one retired (see {@code BulkRetireService}),
    22	 * and a viewer's generate of the plans' claims with none made (see {@code PlanService}).
    23	 * A clone is let through too: it changes nothing on the sheet, and only a steward may make one (see
    24	 * {@code CloneService}), so an archived sheet can still be cloned.
    25	 */
    26	@Component
    27	public class ViewerGuard implements HandlerInterceptor {
    28	
    29	    /** The path of a sheet's requests; the sheet id is the segment after it. */
    30	    public static final String SHEETS = "/api/sheets/";
    31	
    32	    static final Set<String> LET_THROUGH = Set.of("load", "claims/open", "claims/settle", "claims/reassign", "claims/redate", "claims/void", "people/grade", "clone",
    33	            "people/retire", "plans/generate");
    34	
    35	    private final SettingService settings;
    36	
    37	    public ViewerGuard(SettingService settings) {
    38	        this.settings = settings;
    39	    }
    40	
    41	    @Override
    42	    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
    43	        if (HttpMethod.GET.matches(request.getMethod())) return true;
    44	        String path = request.getRequestURI().substring(request.getContextPath().length());
    45	        String header = request.getHeader(SignedInUser.HEADER);
    46	        if (!path.startsWith(SHEETS) || header == null || header.isBlank()) return true;
    47	        String rest = path.substring(SHEETS.length());
    48	        int slash = rest.indexOf('/');
    49	        if (slash < 0 || LET_THROUGH.contains(rest.substring(slash + 1))) return true;
    50	        String sheetId = URLDecoder.decode(rest.substring(0, slash), StandardCharsets.UTF_8).trim();
    51	        if (settings.roleOf(sheetId, SignedInUser.name(header)) == Role.VIEWER) {
    52	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "A viewer cannot change anything.");
    53	        }
    54	        return true;
    55	    }
    56	}
