    15	@Service
    16	public class ImportPeopleService {
    17	
    18	    /** A pasted line, read: the person's fields as the person form takes them; no grade when it is blank. */
    19	    private record Line(int number, String name, Grade grade, Integer terms, String contact) {
    20	    }
    21	
    22	    /** What an import did: the people of its lines, in order, and how many it added and how many it updated. */
    23	    public record Result(List<Person> people, int added, int updated) {
    24	    }
    25	
    26	    private final PersonService service;
    27	    private final PersonRepository repository;
    28	    private final SheetSettingRepository settings;
    29	
    30	    public ImportPeopleService(PersonService service, PersonRepository repository, SheetSettingRepository settings) {
    31	        this.service = service;
    32	        this.repository = repository;
    33	        this.settings = settings;
    34	    }
    35	
    36	    /** Add or update a person per pasted line of name,grade,terms,contact, in order, each as the person
    37	     *  form would. A line whose name matches a person on the sheet, by name or alias as names are compared,
    38	     *  updates them: their grade from the sheet's today, and their terms and contact when the line gives
    39	     *  them. Other lines add a person. Every line is read first with the form's rules; one change: when any
    40	     *  line is refused, nothing is imported and nothing is written. Blank lines are skipped; a paste with
    41	     *  no lines is refused, as is one repeating a name or a contact of an earlier line, compared as the
    42	     *  form compares them, or naming the same person as an earlier line. A line with a blank grade takes
    43	     *  the sheet's default grade. */
    44	    @Transactional
    45	    public Result importPeople(String sheetId, String user, String text) {
    46	        List<Line> lines = new ArrayList<>();
    47	        Set<String> names = new HashSet<>();
    48	        Set<String> contacts = new HashSet<>();
    49	        int number = 0;
    50	        for (String raw : text.split("\\r?\\n")) {
    51	            number++;
    52	            if (raw.isBlank()) continue;
    53	            Line line = read(raw, number);
    54	            if (!names.add(Person.keyOf(line.name()))) {
    55	                throw refused(number, "the name '" + line.name() + "' is repeated");
    56	            }
    57	            String contactKey = Person.contactOf(line.contact());
    58	            if (contactKey != null && !contacts.add(contactKey)) {
    59	                throw refused(number, "the contact '" + contactKey + "' is repeated");
    60	            }
    61	            lines.add(line);
    62	        }
    63	        if (lines.isEmpty()) {
    64	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Paste at least one line.");
    65	        }
    66	        Grade defaultGrade = SettingService.defaultGradeOf(settings, sheetId);
    67	        List<Person> people = new ArrayList<>();
    68	        Set<Long> updatedIds = new HashSet<>();
    69	        int added = 0;
    70	        for (Line line : lines) {
    71	            Optional<Person> match = repository.findByNameOrAlias(sheetId, Person.keyOf(line.name()));
    72	            try {
    73	                if (match.isPresent()) {
    74	                    Person person = match.get();
    75	                    if (!updatedIds.add(person.getId())) {
    76	                        throw refused(line.number(), "'" + person.getName() + "' is named by an earlier line");
    77	                    }
    78	                    people.add(service.update(sheetId, user, person.getId(), person.getVersion(), person.getName(),
    79	                            gradeOf(line, defaultGrade), null, line.terms() != null ? line.terms() : person.getTerms(),
    80	                            line.contact().isEmpty() ? person.getContact() : line.contact()));
    81	                } else {
    82	                    people.add(service.add(sheetId, user, line.name(), gradeOf(line, defaultGrade), line.terms(), line.contact()));
    83	                    added++;
    84	                }
    85	            } catch (ResponseStatusException e) {
    86	                if (e.getReason() != null && e.getReason().startsWith("Line ")) throw e;
    87	                throw new ResponseStatusException(e.getStatusCode(), "Line " + line.number() + ": " + e.getReason());
    88	            }
    89	        }
    90	        return new Result(people, added, updatedIds.size());
    91	    }
    92	
    93	    private static Grade gradeOf(Line line, Grade defaultGrade) {
    94	        return line.grade() != null ? line.grade() : defaultGrade;
    95	    }
    96	
    97	    /** A line of name,grade,terms,contact; the grade may be blank, and the terms and contact blank or absent. */
    98	    private static Line read(String raw, int number) {
    99	        String[] fields = raw.split(",", 4);
   100	        if (fields.length < 2) throw refused(number, "it needs at least a name and a grade");
   101	        String name = fields[0].trim();
   102	        if (name.isEmpty()) throw refused(number, "the name is blank");
   103	        if (name.length() > 200) throw refused(number, "the name is longer than 200 characters");
   104	        Grade grade = null;
   105	        try {
   106	            if (!fields[1].isBlank()) grade = Grade.valueOf(fields[1].trim());
   107	        } catch (IllegalArgumentException e) {
   108	            throw refused(number, "the grade is not one of A, B or C");
   109	        }
   110	        String terms = fields.length > 2 ? fields[2].trim() : "";
   111	        if (!terms.matches("\\d{0,5}")) throw refused(number, "the terms are not a whole number of days");
   112	        String contact = fields.length > 3 ? fields[3].trim() : "";
   113	        if (contact.length() > 200) throw refused(number, "the contact is longer than 200 characters");
   114	        return new Line(number, name, grade, terms.isEmpty() ? null : Integer.valueOf(terms), contact);
   115	    }
   116	
   117	    private static ResponseStatusException refused(int number, String why) {
   118	        return new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Line " + number + ": " + why + ".");
   119	    }
   120	}
