193	     *  is no longer a draft is refused: to change an open claim, void it and add a new one. A claim
194	     *  another user's editor locks is refused; saving releases the user's own lock. A save whose date's
195	     *  due-by, as a claim of its person added on it would be fixed now, falls inside a closed period is
196	     *  refused, the date unchanged or not; the claim's own due-by stays as it was fixed. */
197	    @Transactional
198	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
199	            String corrects, String ref, String tags) {
200	        Claim claim = claims.findForUpdate(id, sheetId)
201	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
202	        LocalDate dated = dateOr(sheetId, date);
203	        refuseIfClosed(sheetId, claim.getDueBy());
204	        refuseUnlessDraft(claim);
205	        refuseIfLocked(claim, user);
206	        Person person = person(sheetId, claim.getPersonId());
