208	        refuseIfClosed(sheetId, holidays.dueBy(sheetId, dated, termsOf(sheetId, person)));
209	        if (!claim.getLines().isEmpty() && amount.compareTo(claim.getAmount()) != 0) {
210	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
211	                    "A claim with lines has the total of its lines as its amount.");
212	        }
