214	        String reference = refOf(ref);
215	        refuseIfRefUsed(sheetId, reference, claim.getId());
216	        Rollup.Snapshot before = rollup.snapshot(sheetId);
217	        claim.set(amount, dated, noteOf(note), corrects);
218	        claim.setRef(reference);
219	        List<String> tagged = tagsOf(tags);
220	        claim.setTags(tagged);
221	        useTags(sheetId, tagged);
222	        claim.lockFor(null);
223	        claim.setEditedBy(user);
224	        Claim saved = claims.saveAndFlush(claim);
