240	    /** Make the claims a bulk settle settled (or left pending) the sheet's next settle batch: each shows
241	     *  its number. Its audit line, after the claims' own, carries the batch's number, how many claims it
242	     *  has and the frozen dues of those SETTLED added up. Returns the batch's number. */
243	    @Transactional
244	    public int markSettleBatch(String sheetId, String user, List<Claim> settled) {
245	        int batch = sheets.nextSettleBatch(sheetId);
246	        BigDecimal total = BigDecimal.ZERO.setScale(2);
247	        for (Claim claim : settled) {
248	            Claim row = claims.findForUpdate(claim.getId(), sheetId).orElseThrow();
249	            row.setSettleBatch(batch);
250	            claims.save(row);
251	            claim.setSettleBatch(batch);
252	            if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
253	                total = total.add(claim.getSettledDue());
254	            }
255	        }
256	        claims.flush();
257	        audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + batch
258	                + " count=" + settled.size() + " total=" + total.toPlainString());
259	        return batch;
260	    }
