291	    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason, boolean judged,
292	            SettledAsOf asOf) {
293	        Claim claim = claims.findForUpdate(id, sheetId)
294	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
295	        refuseIfClosed(sheetId, claim.getDueBy());
296	        boolean voidingSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
297	        if (voidingSettled) {
298	            refuseUnlessSettledVoidable(sheetId, user, claim);
299	        } else if (!claim.getStatus().canBecome(next)) {
300	            throw new ResponseStatusException(HttpStatus.CONFLICT,
301	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
302	        } else {
303	            settings.refuseUnlessPermitted(sheetId, user, ACTIONS.get(next),
304	                    "Your role may not " + ACTIONS.get(next) + " a claim on this sheet.");
305	        }
306	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
307	            throw new ResponseStatusException(HttpStatus.CONFLICT,
308	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be settled before then.");
309	        }
310	        if (!judged) refuseUnlessFourEyes(next, user, claim);
311	        String voidReason = next == ClaimStatus.VOID ? voidReasons.reasonToVoid(sheetId, reason) : null;
312	        Person person = person(sheetId, claim.getPersonId());
313	        if (next == ClaimStatus.OPEN && person.isFlaggedOn(sheets.today(sheetId))
314	                && settings.roleOf(sheetId, user) != Role.STEWARD) {
315	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
316	                    "The person is flagged; only a steward may open their claim.");
317	        }
318	        // Worked out while the claim is still open: settling freezes the due, its late charge included.
319	        BigDecimal dueNow = next != ClaimStatus.SETTLED ? null : asOf != null ? asOf.due() : due(sheetId, person, claim);
320	        if (next == ClaimStatus.SETTLED && !judged) refuseIfUnproven(sheetId, person, claim, dueNow);
321	        BigDecimal dueOpening = next == ClaimStatus.OPEN ? due(sheetId, person, claim) : null;
322	        if (next == ClaimStatus.OPEN) refuseIfUnnoted(sheetId, claim, dueOpening);
323	        if (next == ClaimStatus.OPEN) refuseIfCapped(sheetId, claim);
324	        // Opened with a due above the review threshold, it waits for a steward's review, with no number yet.
325	        if (next == ClaimStatus.OPEN && isAboveReviewThreshold(sheetId, claim, dueOpening)) next = ClaimStatus.REVIEW;
326	        // Settled one at a time until a bulk settle marks it with its batch.
327	        if (next == ClaimStatus.SETTLED) claim.setSettleBatch(null);
328	        if (next == ClaimStatus.SETTLED && isAboveClerkLimit(sheetId, user, person, dueNow)) next = ClaimStatus.PENDING;
329	        Rollup.Snapshot before = rollup.snapshot(sheetId);
330	        String number = next == ClaimStatus.OPEN ? nextNumber(sheetId, claim) : claim.getNumber();
331	        claim.setStatus(next);
332	        if (next == ClaimStatus.OPEN || next == ClaimStatus.REVIEW) claim.setOpenedBy(user);
333	        // A voided claim keeps its number, which is never given to another claim.
334	        claim.setNumber(number);
335	        if (next == ClaimStatus.SETTLED) claim.setSettledDue(dueNow);
336	        if (next == ClaimStatus.VOID) claim.setVoidReason(voidReason);
337	        logStatus(sheetId, user, person, claim);
338	        Claim saved = claims.saveAndFlush(claim);
339	        String event = EVENTS.get(next);
340	        if (next == ClaimStatus.SETTLED) {
341	            recordChange(event, user, person, saved, number, " due=" + text(saved.getSettledDue())
342	                    + (asOf == null ? "" : " on=" + asOf.on()));
343	            notifyWatchers(user, person, saved);
344	        } else if (voidingSettled) {
345	            recordChange(event, user, person, saved, number, " reversed=" + text(saved.getSettledDue())
346	                    + reasonField(voidReason));
347	        } else {
348	            recordChange(event, user, person, saved, number, reasonField(voidReason));
349	        }
350	        rollup.recordChanges(user, before);
351	        return saved;
352	    }
