426	    /** Split an amount (more than 0.00 and less than the claim's amount) off an OPEN claim into a new
427	     *  OPEN claim of the same person, date and note, given the next number, opened by the user and due
428	     *  by the terms in force on the date; the claim keeps the rest and loses any figure a statement bound
429	     *  it to; it is a late entry when its due-by falls inside a soft-closed period. Refused for a claim that
430	     *  is not OPEN (a PENDING one included), a deferred claim, and a claim whose due-by, or the new claim's,
431	     *  is inside a closed period, or when the sheet's permission matrix does not let the user open. */
432	    @Transactional
433	    public Split split(String sheetId, String user, long id, BigDecimal part) {
434	        Claim claim = claims.findForUpdate(id, sheetId)
435	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
436	        refuseIfClosed(sheetId, claim.getDueBy());
437	        if (claim.getStatus() != ClaimStatus.OPEN) {
438	            throw new ResponseStatusException(HttpStatus.CONFLICT,
439	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can.");
440	        }
441	        // The claim split off is opened by the user, so the permission matrix must let them open.
442	        settings.refuseUnlessPermitted(sheetId, user, ACTIONS.get(ClaimStatus.OPEN),
443	                "Your role may not " + ACTIONS.get(ClaimStatus.OPEN) + " a claim on this sheet.");
444	        if (claim.isDeferredOn(sheets.today(sheetId))) {
445	            throw new ResponseStatusException(HttpStatus.CONFLICT,
446	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be split.");
447	        }
448	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
449	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
450	                    "The amount split off must be more than 0.00 and less than the claim's amount.");
451	        }
452	        Person person = person(sheetId, claim.getPersonId());
453	        // The terms are fixed now, those in force on the sheet's today; the due-by counts them in business days.
454	        int terms = termsOf(sheetId, person);
455	        LocalDate dueBy = holidays.dueBy(sheetId, claim.getDate(), terms);
456	        refuseIfClosed(sheetId, dueBy);
457	        Rollup.Snapshot before = rollup.snapshot(sheetId);
458	        Claim split = claim.splitOff(part, null, user, terms, dueBy, sheets.today(sheetId));
459	        String number = nextNumber(sheetId, split);
460	        split.setNumber(number);
461	        // Split off into a soft-closed period, the new claim is a late entry of it.
462	        if (periods.isSoftClosedOn(sheetId, dueBy)) split.markLateEntry();
463	        split.setListed(claims.lastListed(sheetId) + 1);
464	        Claim saved = claims.saveAndFlush(claim);
465	        split = claims.saveAndFlush(split);
466	        logStatus(sheetId, user, person, split);
467	        recordChange("CLAIM_SPLIT", user, person, saved, saved.getNumber(), " into=" + number);
468	        recordChange("CLAIM_OPENED", user, person, split);
469	        rollup.recordChanges(user, before);
470	        return new Split(saved, split);
471	    }
