473	    /** Part-settle an OPEN claim: split the amount off it, as {@link #split}, and settle the new claim at once
474	     *  by the user, as settling does (PENDING when the clerk limit says so). The four-eyes rules and the proof
475	     *  rule are judged on the claim as it was before the split; the new claim's opener is the user. A split or
476	     *  settle that would be refused refuses the whole, changing nothing. */
477	    @Transactional
478	    public Split settlePart(String sheetId, String user, long id, BigDecimal part) {
479	        Claim claim = claims.findForUpdate(id, sheetId)
480	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
481	        refuseUnlessFourEyes(ClaimStatus.SETTLED, user, claim);
482	        if (claim.getStatus() == ClaimStatus.OPEN) {
483	            Person person = person(sheetId, claim.getPersonId());
