946	     *  the person already has that many OPEN or PENDING claims in it. The sheet is locked, so two opens
947	     *  cannot both pass the cap. */
948	    private void refuseIfCapped(String sheetId, Claim claim) {
949	        if (claim.getDueBy() == null) return;
950	        Period period = periodOf(sheetId, claim.getDueBy());
951	        if (period == null || period.getCap() == null) return;
952	        long held = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
953	                .filter((c) -> !c.getId().equals(claim.getId()) && c.getPersonId().equals(claim.getPersonId())
954	                        && c.getStatus().isOpen() && c.getDueBy() != null && period.contains(c.getDueBy()))
955	                .count();
956	        if (held >= period.getCap()) {
957	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person already has " + period.getCap()
958	                    + " open claims in period " + period.getName() + ".");
959	        }
960	    }
