1034	    /** The figure under the claim's due: the due fixed when it was settled, else the due as shown that
1035	     *  its person's last statement bound it to (a PENDING claim included), else its live rate figure, before any late charge and floor;
1036	     *  null when that is n/a. */
1037	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
1038	        if (claim.getSettledDue() != null) return claim.getSettledDue();
1039	        if (claim.isBound()) return claim.getStatedDue();
1040	        return dueNow(sheetId, person, claim);
