1043	    /** The claim's rate figure now: at the rate in force on the claim's date of its person's grade in
1044	     *  force on that date, of the versions of the rates that apply to the claim, rounded as the claim's {@link Rounding} decides, before any late charge and
1045	     *  floor; null when no rate of the grade applies by then. */
1046	    private BigDecimal dueNow(String sheetId, Person person, Claim claim) {
1047	        Rate rate = rates.inForceFor(sheetId, person.gradeOn(claim.getDate()), claim.getDate(), claim.getId());
1048	        if (rate == null) return null;
1049	        return claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2,
1050	                rounding(sheetId, claim));
1051	    }
