1053	    /** How many claims a candidate rate would change and by how much in all. */
1054	    public record RatePreview(int count, BigDecimal diff) {
1055	    }
1056	
1057	    /** What a candidate percent for a grade, applied on every date, would do to the OPEN and PENDING claims of
1058	     *  people on that grade on the claim's date: how many would show a different due, and the sum of new due
1059	     *  less current due (an n/a due counting as 0.00). A claim bound by a statement does not change; nothing is saved. */
1060	    @Transactional(readOnly = true)
1061	    public RatePreview previewRate(String sheetId, Grade grade, BigDecimal pct) {
1062	        Map<Long, Person> byId = new HashMap<>();
1063	        for (Person p : people.findInListOrder(sheetId)) byId.put(p.getId(), p);
1064	        int count = 0;
1065	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
1066	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
1067	            if (!claim.getStatus().isOpen() || claim.isBound() || claim.getSettledDue() != null) continue;
1068	            Person person = byId.get(claim.getPersonId());
1069	            if (person == null || person.gradeOn(claim.getDate()) != grade) continue;
1070	            RoundingMode rounding = rounding(sheetId, claim);
1071	            BigDecimal figure = claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding);
1072	            BigDecimal next = LateCharge.dueOf(claim, figure, settings.floor(sheetId, claim.getDate()),
1073	                    sheets.today(sheetId), grace(sheetId, person, claim), settings.dated(sheetId)::latePctOn, rounding);
1074	            BigDecimal current = due(sheetId, person, claim);
1075	            if (current != null && current.compareTo(next) == 0) continue;
1076	            count++;
1077	            diff = diff.add(next.subtract(current == null ? BigDecimal.ZERO : current));
1078	        }
1079	        return new RatePreview(count, diff.setScale(2));
1080	    }
