     9	/**
    10	 * The late charge on a claim: an open claim past its due-by (fixed when it was added) gains, for every
    11	 * full 30 days it is overdue, the sheet's late percent in force on that boundary (the due-by plus 30, 60,
    12	 * 90 ... days, counted from the due-by plus the grace days of its person's grade, if any) of its figure plus the
    13	 * charges of the boundaries before it (compounding), each rounded as the claim's {@link Rounding} decides, like due, and added up;
    14	 * a boundary whose percent is 0.00 adds nothing, and a correction or a waived claim gains none. The floor is applied first:
    15	 * the charge is worked out on the rate figure held to at least the floor. A statement binds the due as shown, floor and
    16	 * charge included: while the claim is bound its due is that figure and the charge no longer follows the sheet's today.
    17	 */
    18	public final class LateCharge {
    19	
    20	    /** The days a claim must be overdue for each step of the late charge. */
    21	    public static final int DAYS_PER_CHARGE = 30;
    22	
    23	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);
    24	
    25	    private LateCharge() {
    26	    }
    27	
    28	    /** The late charge on the claim of the figure (null: n/a, and no charge) on the sheet's today; none
    29	     *  while the claim is deferred, as it is not overdue then. */
    30	    public static BigDecimal of(Claim claim, BigDecimal figure, LocalDate today,
    31	            int grace, Function<LocalDate, BigDecimal> latePctOn, RoundingMode rounding) {
    32	        return claim.getStatus().isOpen() && !claim.isDeferredOn(today) ? asOpen(claim, figure, today, grace, latePctOn, rounding) : ZERO;
    33	    }
    34	
    35	    /** The late charge the claim of the figure would have on the sheet's today were it open. */
    36	    private static BigDecimal asOpen(Claim claim, BigDecimal figure, LocalDate today,
    37	            int grace, Function<LocalDate, BigDecimal> latePctOn, RoundingMode rounding) {
    38	        if (figure == null || today == null || claim.isCorrection() || claim.isWaived()) return ZERO;
    39	        LocalDate lateFrom = lateFrom(claim, grace);
    40	        long overdueDays = ChronoUnit.DAYS.between(lateFrom, today);
    41	        long steps = overdueDays <= 0 ? 0 : overdueDays / DAYS_PER_CHARGE;
    42	        BigDecimal charge = ZERO;
    43	        for (long step = 1; step <= steps; step++) {
    44	            BigDecimal pct = latePctOn.apply(lateFrom.plusDays(step * DAYS_PER_CHARGE));
    45	            charge = charge.add(figure.add(charge).multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding));
    46	        }
    47	        return charge;
    48	    }
    49	
    50	    /** The claim's due of the figure (null: n/a): a due fixed when it was settled, or bound by a statement, stays as it is; else the
    51	     *  figure held to at least the floor, with the late charge worked out on that floored figure on top (a
    52	     *  correction has no floor and no charge); null when the figure is n/a. */
    53	    public static BigDecimal dueOf(Claim claim, BigDecimal figure, BigDecimal floor, LocalDate today,
    54	            int grace, Function<LocalDate, BigDecimal> latePctOn, RoundingMode rounding) {
    55	        if (figure == null || claim.getSettledDue() != null || claim.isBound()) return figure;
    56	        BigDecimal floored = floored(claim, figure, floor);
    57	        return floored.add(of(claim, floored, today, grace, latePctOn, rounding));
    58	    }
    59	
    60	    /** The claim's due of the figure as it would be were the claim open: the
    61	     *  figure held to at least the floor, with the late charge it would have on that floored figure on top;
    62	     *  null when the figure is n/a. */
    63	    public static BigDecimal dueAsOpen(Claim claim, BigDecimal figure, BigDecimal floor, LocalDate today,
    64	            int grace, Function<LocalDate, BigDecimal> latePctOn, RoundingMode rounding) {
    65	        if (figure == null) return null;
    66	        BigDecimal floored = floored(claim, figure, floor);
    67	        return floored.add(asOpen(claim, floored, today, grace, latePctOn, rounding));
    68	    }
    69	
    70	    /** The date the claim's lateness counts from: its due-by plus the grace days of its person's grade in
    71	     *  force on its date; the due-by shown is unchanged. */
    72	    public static LocalDate lateFrom(Claim claim, int grace) {
    73	        return claim.getDueBy().plusDays(grace);
    74	    }
    75	
    76	    /** The due held to at least the floor, unless the claim is a correction, which has no floor. */
    77	    public static BigDecimal floored(Claim claim, BigDecimal due, BigDecimal floor) {
    78	        return claim.isCorrection() ? due : due.max(floor);
    79	    }
    80	}
