     5	
     6	/**
     7	 * How a claim's live figures round (the rate step and the late charge): half up when the claim is dated
     8	 * before the sheet's policy date, half to even when on or after it. A correction rounds by the date of
     9	 * the claim it corrects, not its own. The policy date is the sheet's today when it is blank. A rounding
    10	 * mode the sheet has in force on that date (see {@code DatedSettings#roundingOn}) overrides the policy date.
    11	 */
    12	public final class Rounding {
    13	
    14	    private Rounding() {
    15	    }
    16	
    17	    /** The policy date in force: the one the sheet set, else its today (null when neither is known). */
    18	    public static LocalDate policyDate(LocalDate set, LocalDate today) {
    19	        return set != null ? set : today;
    20	    }
    21	
    22	    /** The date that decides how the claim rounds: the date of the claim it corrects (when that is
    23	     *  known), else its own. */
    24	    public static LocalDate dateOf(Claim claim, Claim corrected) {
    25	        return claim.isCorrection() && corrected != null ? corrected.getDate() : claim.getDate();
    26	    }
    27	
    28	    /** How a claim whose rounding is decided by the date rounds under the policy date. */
    29	    public static RoundingMode of(LocalDate roundsBy, LocalDate policyDate) {
    30	        return policyDate != null && roundsBy.isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    31	    }
    32	
    33	    /** How a claim whose rounding is decided by the date rounds: by the rounding mode in force on that
    34	     *  date when there is one, else under the policy date. */
    35	    public static RoundingMode of(LocalDate roundsBy, LocalDate policyDate, RoundingMode inForce) {
    36	        return inForce != null ? inForce : of(roundsBy, policyDate);
    37	    }
    38	
    39	    /** The rounding mode a setting value names (half-up or half-even), or null when it names none. */
    40	    public static RoundingMode mode(String value) {
    41	        if (value == null) return null;
    42	        return switch (value) {
    43	            case "half-up" -> RoundingMode.HALF_UP;
    44	            case "half-even" -> RoundingMode.HALF_EVEN;
    45	            default -> null;
    46	        };
    47	    }
    48	}
