    44	                .filter(c -> c.getStatus() != ClaimStatus.VOID && c.getStatus() != ClaimStatus.DELETED)
    45	                .collect(Collectors.groupingBy(Claim::getPersonId));
    46	        List<Duplicate> found = new ArrayList<>();
    47	        for (Person person : people.findInListOrder(sheetId)) {
    48	            List<Claim> theirs = byPerson.get(person.getId());
    49	            if (theirs == null) continue;
    50	            Map<Key, Long> counts = theirs.stream().collect(Collectors.groupingBy(
    51	                    c -> new Key(c.getDate(), c.getAmount().setScale(2, RoundingMode.HALF_EVEN)),
    52	                    () -> new TreeMap<>(ORDER), Collectors.counting()));
