    16	/**
    17	 * A claim's due as it stood at the end of a date, as the as-of view works it out: in a transaction of
    18	 * its own that puts the sheet back to what {@link SheetHistory} kept for that date (with the date as its
    19	 * today) and is always rolled back, so the store and the audit file are left as they were. It runs before
    20	 * the change that uses it takes any lock on the sheet's rows, which putting the sheet back rewrites.
    21	 */
    22	@Service
    23	public class ClaimAsOfService {
    24	
    25	    /** The claim's due at the end of a date; null when it was n/a. */
    26	    public record DueAsOf(BigDecimal due) {
    27	    }
    28	
    29	    private final SheetHistory history;
    30	    private final SheetService sheets;
    31	    private final ClaimRepository claims;
    32	    private final PersonRepository people;
    33	    private final ClaimService service;
    34	    private final TransactionTemplate transaction;
    35	    @PersistenceContext
    36	    private EntityManager entities;
    37	
    38	    public ClaimAsOfService(SheetHistory history, SheetService sheets, ClaimRepository claims, PersonRepository people,
    39	            ClaimService service, PlatformTransactionManager transactions) {
    40	        this.history = history;
    41	        this.sheets = sheets;
    42	        this.claims = claims;
    43	        this.people = people;
    44	        this.service = service;
    45	        this.transaction = new TransactionTemplate(transactions);
    46	    }
    47	
    48	    /** The claim's due at the end of the date; refused (422) for a date after the sheet's today, and for a
    49	     *  claim that did not exist at the end of it. */
    50	    public DueAsOf dueAsOf(String sheetId, long id, LocalDate on) {
    51	        return transaction.execute((status) -> {
    52	            status.setRollbackOnly();
    53	            if (claims.findByIdAndSheetId(id, sheetId).isEmpty()) {
    54	                throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim.");
    55	            }
    56	            LocalDate today = sheets.today(sheetId);
    57	            if (today == null || on.isAfter(today)) {
    58	                throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
    59	                        "A claim can only be settled as of a date on or before the sheet's today.");
    60	            }
    61	            history.restoreWithParents(sheetId, on);
    62	            // What was read before the sheet was put back is no longer what it holds.
    63	            entities.clear();
    64	            Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(() -> new ResponseStatusException(
    65	                    HttpStatus.UNPROCESSABLE_ENTITY, "The claim did not exist on " + on + "."));
    66	            return new DueAsOf(people.findByIdAndSheetId(claim.getPersonId(), sheetId)
    67	                    .map((person) -> service.due(sheetId, person, claim))
    68	                    .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
    69	                            "The claim did not exist on " + on + ".")));
    70	        });
    71	    }
    72	}
