    13	    /** Whether the day is a business day, given the sheet's holidays. */
    14	    public static boolean isBusinessDay(LocalDate day, Set<LocalDate> holidays) {
    15	        DayOfWeek dow = day.getDayOfWeek();
    16	        return dow != DayOfWeek.SATURDAY && dow != DayOfWeek.SUNDAY && !holidays.contains(day);
    17	    }
    18	
    19	    /** The terms-th business day after the date, counting forward from the day after it; the date
    20	     *  itself for terms of 0. */
    21	    public static LocalDate after(LocalDate date, int terms, Set<LocalDate> holidays) {
    22	        LocalDate day = date;
    23	        for (int counted = 0; counted < terms;) {
    24	            day = day.plusDays(1);
    25	            if (isBusinessDay(day, holidays)) counted++;
    26	        }
    27	        return day;
    28	    }
    29	}

