    22	@Service
    23	public class PasteClaimsService {
    24	
    25	    /** A pasted line, read: the person it names and the claim's fields (no date: the sheet's entry date,
    26	     *  else its today; no ref: no reference). */
    27	    private record Line(Person person, BigDecimal amount, LocalDate date, String note, String ref) {
    28	    }
    29	
    30	    private final PersonRepository people;
    31	    private final ClaimRepository claims;
    32	    private final ClaimService claimService;
    33	
    34	    public PasteClaimsService(PersonRepository people, ClaimRepository claims, ClaimService claimService) {
    35	        this.people = people;
    36	        this.claims = claims;
    37	        this.claimService = claimService;
    38	    }
    39	
    40	    /** Add and open a claim per pasted line of name,amount,date,note, in order. Every line is read first,
    41	     *  then each is added with the claim form's rules and opened by the user as the open button would;
    42	     *  one change: when any line is refused, nothing is added and nothing is written. A line whose person,
    43	     *  date and note match one of their claims as it stood before the paste updates that claim instead: a
    44	     *  DRAFT is edited to the line's amount (when it differs) and opened; a claim in any other status is
    45	     *  refused. Blank lines are skipped; a paste with no lines is refused, as is one giving a reference
    46	     *  already used on the sheet or by an earlier line, compared without regard to case. Returns the
    47	     *  lines' claims, in the order of their lines. */
    48	    @Transactional
    49	    public List<Claim> paste(String sheetId, String user, String text) {
    50	        List<Line> lines = new ArrayList<>();
    51	        List<Claim> matches = new ArrayList<>();
    52	        Set<String> refs = new HashSet<>();
    53	        List<Claim> existing = claims.findBySheetIdOrderByListedDesc(sheetId);
    54	        LocalDate undated = claimService.entryDateOr(sheetId);
    55	        int number = 0;
    56	        for (String raw : text.split("\\r?\\n")) {
    57	            number++;
    58	            if (raw.isBlank()) continue;
    59	            Line line = read(sheetId, raw, number);
    60	            if (line.ref() != null && (!refs.add(line.ref().toLowerCase(Locale.ROOT))
    61	                    || claims.refUsed(sheetId, line.ref(), null))) {
    62	                throw refused(number, "the reference '" + line.ref() + "' is already used");
    63	            }
    64	            Claim match = match(existing, line, line.date() != null ? line.date() : undated);
    65	            if (match != null && match.getStatus() != ClaimStatus.DRAFT) {
    66	                throw refused(number, "it matches a " + match.getStatus() + " claim, which cannot be updated");
    67	            }
    68	            lines.add(line);
    69	            matches.add(match);
    70	        }
    71	        if (lines.isEmpty()) {
    72	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Paste at least one line.");
    73	        }
    74	        List<Claim> done = new ArrayList<>();
    75	        for (int i = 0; i < lines.size(); i++) {
    76	            Line line = lines.get(i);
    77	            Claim claim = matches.get(i);
    78	            if (claim == null) {
    79	                claim = claimService.add(sheetId, user, line.person().getId(), line.amount(), line.date(),
    80	                        line.note(), null, line.ref(), null);
    81	            } else if (claim.getAmount().compareTo(line.amount()) != 0) {
    82	                claim = claimService.update(sheetId, user, claim.getId(), line.amount(), claim.getDate(),
    83	                        claim.getNote(), claim.getCorrects(), line.ref() != null ? line.ref() : claim.getRef(),
    84	                        String.join(",", claim.getTags()));
    85	            }
    86	            done.add(claimService.changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
    87	        }
    88	        return done;
    89	    }
    90	
    91	    /** The person's claim, as it stood before the paste, dated the date with the line's note; null when none. */
    92	    private static Claim match(List<Claim> existing, Line line, LocalDate date) {
    93	        return existing.stream()
    94	                .filter((c) -> c.getPersonId().equals(line.person().getId()) && date.equals(c.getDate())
    95	                        && line.note().equals(c.getNote()))
    96	                .findFirst().orElse(null);
    97	    }
    98	
    99	    /** A line of name,amount,date,note; the note may hold commas, the date may be blank and the note absent.
   100	     *  A note ending in ' #<reference>' gives the claim that reference, which is not part of the note. */
   101	    private Line read(String sheetId, String raw, int number) {
   102	        String[] fields = raw.split(",", 4);
   103	        if (fields.length < 2) throw refused(number, "it needs at least a name and an amount");
   104	        String name = fields[0].trim();
   105	        Person person = name.isEmpty() ? null
   106	                : people.findByNameOrAlias(sheetId, Person.keyOf(name)).orElse(null);
   107	        if (person == null) throw refused(number, "no one on the sheet is named '" + name + "'");
   108	        BigDecimal amount;
   109	        try {
   110	            amount = new BigDecimal(fields[1].trim());
   111	        } catch (NumberFormatException e) {
   112	            throw refused(number, "the amount is not a number");
   113	        }
   114	        if (amount.scale() > 2 || amount.precision() - amount.scale() > 10) {
   115	            throw refused(number, "the amount has more than two decimals or ten digits");
   116	        }
   117	        LocalDate date = null;
   118	        if (fields.length > 2 && !fields[2].isBlank()) {
   119	            try {
   120	                date = LocalDate.parse(fields[2].trim());
   121	            } catch (DateTimeParseException e) {
   122	                throw refused(number, "the date is not a date (yyyy-mm-dd)");
   123	            }
   124	        }
   125	        String note = fields.length > 3 ? fields[3].trim() : "";
   126	        String ref = null;
   127	        int hash = note.lastIndexOf(" #");
   128	        if (hash >= 0) {
   129	            ref = ClaimService.refOf(note.substring(hash + 2));
   130	            note = note.substring(0, hash).trim();
   131	        }
   132	        if (ref != null && ref.length() > 220) throw refused(number, "the reference is longer than 220 characters");
   133	        if (note.length() > 1000) throw refused(number, "the note is longer than 1000 characters");
   134	        return new Line(person, amount, date, note, ref);
   135	    }
   136	
   137	    private static ResponseStatusException refused(int number, String why) {
   138	        return new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Line " + number + ": " + why + ".");
   139	    }
   140	}
