    75	    /** The plan dates, oldest first, on or before both its end and the date. */
    76	    List<LocalDate> datesUpTo(LocalDate upTo) {
    77	        LocalDate last = end.isBefore(upTo) ? end : upTo;
    78	        List<LocalDate> dates = new ArrayList<>();
    79	        if (day == null) {
    80	            for (LocalDate d = start; !d.isAfter(last); d = d.plusDays(every)) dates.add(d);
    81	            return dates;
