    35	    public PlanService(PlanRepository plans, PersonRepository people, SheetService sheets, SheetRepository sheetRows,
    36	            ClaimService claims, Audit audit, SettingService settings, PlatformTransactionManager transactions) {
    37	        this.plans = plans;
    38	        this.people = people;
    39	        this.sheets = sheets;
    40	        this.sheetRows = sheetRows;
    41	        this.claims = claims;
    42	        this.audit = audit;
    43	        this.settings = settings;
    44	        this.transaction = new TransactionTemplate(transactions);
    45	    }
    46	
    47	    /** The sheet's plans in the order they were added. */
    48	    @Transactional(readOnly = true)
    49	    public List<Plan> list(String sheetId) {
    50	        return plans.findBySheetIdOrderByIdAsc(sheetId);
    51	    }
    52	
    53	    /** The sheet's today. */
    54	    @Transactional(readOnly = true)
    55	    public LocalDate today(String sheetId) {
    56	        return sheets.today(sheetId);
    57	    }
    58	
    59	    /** Add a plan to a person: refused for an amount not above 0.00, neither or both of an interval and a
    60	     *  day of the month, an interval below 1 day, a day of the month outside 1 to 31, or an end before the
    61	     *  start. No start means the sheet's today. */
    62	    @Transactional
    63	    public Plan add(String sheetId, String user, long personId, BigDecimal amount, LocalDate start, Integer every,
    64	            Integer day, LocalDate end) {
    65	        sheets.load(sheetId);
    66	        sheetRows.findForUpdate(sheetId);
    67	        Person person = people.findByIdAndSheetId(personId, sheetId)
    68	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
    69	        if (amount.signum() <= 0) throw refused("The amount must be more than 0.00.");
    70	        if ((every == null) == (day == null)) throw refused("Give either every (days) or a day of the month.");
    71	        if (every != null && every < 1) throw refused("Every must be a whole number of days, at least 1.");
    72	        if (day != null && (day < 1 || day > 31)) throw refused("The day of the month must be 1 to 31.");
    73	        LocalDate from = start != null ? start : sheets.today(sheetId);
    74	        if (end.isBefore(from)) throw refused("The end date cannot be before the start date.");
    75	        Plan plan = plans.saveAndFlush(new Plan(sheetId, personId, amount.setScale(2), from, every, day,
    76	                end));
    77	        audit.recordOnCommit("PLAN_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
    78	                + " amount=" + plan.getAmount().toPlainString() + " start=" + from + (day != null ? " day=" + day : " every=" + every) + " end=" + end);
    79	        return plan;
    80	    }
    81	
    82	    /** For every plan on the sheet, in the order they were added, make a DRAFT claim of its amount, dated
    83	     *  the plan date with an empty note, for each plan date up to its end and the sheet's today that has
    84	     *  none yet. Each claim is added by the claim form's rules, on its own: a date the form refuses is
    85	     *  skipped and tried again next time. The claims made, oldest first; a viewer makes none. */
    86	    public List<Claim> generate(String sheetId, String user) {
    87	        sheets.load(sheetId);
    88	        if (settings.roleOf(sheetId, user) == Role.VIEWER) return List.of();
    89	        LocalDate today = sheets.today(sheetId);
    90	        List<Claim> made = new ArrayList<>();
    91	        for (Plan plan : plans.findBySheetIdOrderByIdAsc(sheetId)) {
    92	            for (LocalDate date : plan.datesUpTo(today)) {
    93	                if (plan.hasGenerated(date)) continue;
    94	                try {
    95	                    Claim claim = transaction.execute((status) -> generateOn(sheetId, user, plan.getId(), date));
    96	                    if (claim != null) made.add(claim);
    97	                } catch (ResponseStatusException refused) {
    98	                    // The claim form refuses the date: it is tried again by the next generate.
    99	                }
   100	            }
   101	        }
   102	        return made;
   103	    }
   104	
   105	    /** Make the plan's claim for the date, unless it has one already. */
   106	    private Claim generateOn(String sheetId, String user, long planId, LocalDate date) {
   107	        Plan plan = plans.findForUpdate(planId).orElse(null);
   108	        if (plan == null || plan.hasGenerated(date)) return null;
   109	        Claim claim = claims.add(sheetId, user, plan.getPersonId(), plan.getAmount(), date, "", null, null, null);
   110	        plan.markGenerated(date);
   111	        plans.saveAndFlush(plan);
   112	        return claim;
   113	    }
   114	
   115	    private static ResponseStatusException refused(String why) {
   116	        return new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, why);
   117	    }
   118	}

package net.officefloor.hq.app.claim;


@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class ClaimController {

    /** What the screen shows of a claim; the amount always has two decimals. The settled due is the
     *  due fixed when the claim was settled, or null when its due is live. Opened by is who opened
     *  the claim, or null when it was never opened. Stated is whether the person's last statement bound
     *  the claim; stated due is the figure it bound it to, or null when unbound or n/a then. Corrects is
     *  the number of the claim a correction corrects, or null when the claim is not a correction. The log is
     *  its status log, oldest first. Deferred until is the date the claim was last deferred until, or null when
     *  it never was; it is deferred while it is OPEN and the sheet's today is before that date. Proofs is
     *  the claim's proofs count; proofs receipt and proofs photo its count of each kind. Split from is the number of the claim it was split off from, or null.
     *  Reminded is the last day a reminder was written for the claim, or null when it never was. Ref is its
     *  external reference, or null when it has none. Tags are its tags, sorted; empty when it has none.
     *  Void reason is the reason it was voided with, or null. Comments are its comments, oldest first.
     *  Lines are its lines, in the order they were added. Edited by is who last edited it, or null when
     *  it never was. Settle batch is the number of the bulk settle batch that settled it, or null when it
     *  was settled one at a time or never. Waived is whether a steward waived its late charge. Held is
     *  whether the claim is held. */
    public record ClaimView(long id, long personId, String amount, LocalDate date, String note,
            ClaimStatus status, String number, String settledDue,
            String openedBy, boolean stated, String statedDue, String corrects, LocalDate dueBy,
            List<LogLineView> log, LocalDate deferredUntil, int proofs, String splitFrom,
            boolean lateEntry, LocalDate reminded, String ref, List<String> tags, String voidReason,
            List<CommentView> comments, String editedBy, Integer settleBatch, List<LineView> lines,
            boolean waived, int proofsReceipt, int proofsPhoto, boolean held) {
        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
                    claim.getCorrects(), claim.getDueBy(), claim.getLog().stream().map(LogLineView::of).toList(),
                    claim.getDeferredUntil(), claim.getProofs(), claim.getSplitFrom(),
                    claim.isLateEntry(), claim.getRemindedOn(), claim.getRef(),
                    claim.getTags(), claim.getVoidReason(),
                    claim.getComments().stream().map(CommentView::of).toList(), claim.getEditedBy(),
                    claim.getSettleBatch(), claim.getLines().stream().map(LineView::of).toList(),
                    claim.isWaived(), claim.getProofs(ProofKind.RECEIPT), claim.getProofs(ProofKind.PHOTO),
                    claim.isHeld());
        }
    }

    /** A line of a claim's status log; the due has two decimals, or is null when it was n/a. */
    public record LogLineView(ClaimStatus status, String by, LocalDate on, String due) {
        public static LogLineView of(ClaimLogLine line) {
            return new LogLineView(line.getStatus(), line.getBy(), line.getOn(),
                    line.getDue() == null ? null : line.getDue().toPlainString());
        }
    }

    /** A comment on a claim: who wrote it, the sheet's today then, and its text. */
    public record CommentView(String by, LocalDate on, String text) {
        public static CommentView of(ClaimComment comment) {
            return new CommentView(comment.getBy(), comment.getOn(), comment.getText());
        }
    }

    /** A line of a claim: its label, quantity and unit amount (two decimals). */
    public record LineView(String label, int qty, String unit) {
        public static LineView of(ClaimLine line) {
            return new LineView(line.getLabel(), line.getQty(), line.getUnit().toPlainString());
        }
    }

    /** A claim's fields, as entered on the form; no date means the sheet's today. A negative amount
     *  is a correction, which names the number of the settled claim it corrects. */
    public record ClaimForm(
            @NotNull @Digits(integer = 10, fraction = 2) BigDecimal amount,
            LocalDate date,
            @Size(max = 1000) String note,
            @Size(max = 220) String corrects,
            @Size(max = 220) String ref,
            @Size(max = 1000) String tags) {
    }

    /** The number a form's correction names, trimmed; none when blank. */
    private static String correctsOf(ClaimForm form) {
        return form.corrects() == null || form.corrects().isBlank() ? null : form.corrects().trim();
    }

