   113	        Pool member = pools.findById(memberPoolId).filter((p) -> p.getSheetId().equals(sheetId))
   114	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
   115	                        "Choose a pool of the sheet."));
   116	        List<Pool> all = pools.findBySheetIdOrderByIdAsc(sheetId);
   117	        Map<Long, Pool> parentOf = new HashMap<>();
   118	        for (Pool p : all) {
   119	            for (PoolMember m : p.getMembers()) {
   120	                if (m.getMemberPoolId() != null) parentOf.put(m.getMemberPoolId(), p);
   121	            }
   122	        }
   123	        if (member.getId().equals(pool.getId())) {
   124	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A pool cannot be a member of itself.");
   125	        }
   126	        Pool parent = parentOf.get(member.getId());
   127	        if (parent != null) {
   128	            throw new ResponseStatusException(HttpStatus.CONFLICT,
   129	                    "The pool " + member.getName() + " is already a member of the pool " + parent.getName() + ".");
   130	        }
   131	        int above = 1;
   132	        for (Pool p = pool; parentOf.containsKey(p.getId()); p = parentOf.get(p.getId())) {
   133	            if (parentOf.get(p.getId()).getId().equals(member.getId())) {
   134	                throw new ResponseStatusException(HttpStatus.CONFLICT,
   135	                        "The pool " + member.getName() + " contains the pool " + pool.getName() + ".");
   136	            }
   137	            above++;
   138	        }
   139	        Map<Long, Pool> byId = new HashMap<>();
   140	        all.forEach((p) -> byId.put(p.getId(), p));
   141	        if (above + depthOf(member, byId) > MAX_DEPTH) {
   142	            throw new ResponseStatusException(HttpStatus.CONFLICT,
   143	                    "A chain of pools may be at most " + MAX_DEPTH + " deep.");
   144	        }
