   157	    /** How many pools deep the pool's chains go: 1 with no member pools. */
   158	    private static int depthOf(Pool pool, Map<Long, Pool> byId) {
   159	        int deepest = 0;
   160	        for (PoolMember m : pool.getMembers()) {
   161	            if (m.getMemberPoolId() != null && byId.containsKey(m.getMemberPoolId())) {
   162	                deepest = Math.max(deepest, depthOf(byId.get(m.getMemberPoolId()), byId));
   163	            }
   164	        }
   165	        return deepest + 1;
   166	    }
