   170	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool."));
   171	    }
   172	
   173	    /** A share as typed: up to two decimals, more than 0.00 and at most 100.00. */
   174	    private static BigDecimal shareOf(String share) {
   175	        String typed = share == null ? "" : share.trim();
   176	        if (!SHARE.matcher(typed).matches() || new BigDecimal(typed).signum() <= 0
   177	                || new BigDecimal(typed).compareTo(HUNDRED) > 0) {
   178	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
   179	                    "Type a share of more than 0.00 and at most 100.00, with up to two decimals.");
   180	        }
   181	        return new BigDecimal(typed).setScale(2);
   182	    }
