   195	            due = LateCharge.floored(claim, figure, floor);
   196	        }
   197	        boolean kept = settled != null || (binding != null && binding.getStatedDue() != null)
   198	                || (figure != null && grade != person.gradeOn(asOf, asOf))
   199	                || (figure != null && !claim.getDate().isAfter(asOf));
