   225	        List<Claim> theirs = claims.findForStatement(sheetId, personId);
   226	        // Only the last statement binds claims, so every claim it bound is unbound.
   227	        LocalDate today = sheets.today(sheetId);
   228	        theirs.forEach((claim) -> claim.unbind(today));
