   239	    /** Only open and settled claims count toward what is claimed and due; a person's open claims, once
   240	     *  their retirement date is reached, do not, unless a statement binds them (a hold leaves them in), nor does a claim deferred on the
   241	     *  sheet's today, as on the screen. */
   242	    private static boolean counts(Person person, Claim claim, LocalDate today) {
   243	        return claim.getStatus() == ClaimStatus.SETTLED
   244	                || (claim.getStatus().isOpen() && !claim.isDeferredOn(today)
   245	                        && (claim.isBound() || !person.isRetiredBy(today)));
   246	    }
   247	}

