});
/** Everyone's due-total added up, skipping the people whose due-total is n/a, not trimmed. */
protected readonly classicDueTotal = computed(() =>
  money(this.people().reduce((t, p) => t + (this.dueCentsOf(p) ?? 0), 0)));
