    41	    public ConsolidatedService(SheetParentRepository parents, Rollup rollup, SheetHistory history,
    42	            EntityManager entityManager) {
    43	        this.parents = parents;
    44	        this.rollup = rollup;
    45	        this.history = history;
    46	        this.entityManager = entityManager;
    47	    }
    48	
    49	    /** The descendants as the store holds them now, or with the date, as every sheet of the tree stood at
    50	     *  the end of that day: only within a transaction that is rolled back (the as-of view's). */
    51	    @Transactional(readOnly = true)
    52	    public Descendants descendantsOf(String sheetId, LocalDate asOf) {
    53	        Set<String> found = asOf == null ? descendantsNow(sheetId) : descendantsAsOf(sheetId, asOf);
    54	        int peopleCount = 0;
    55	        BigDecimal due = BigDecimal.ZERO;
    56	        BigDecimal overdue = BigDecimal.ZERO;
    57	        for (String sheet : found) {
    58	            Rollup.Snapshot figures = rollup.snapshot(sheet);
    59	            peopleCount += figures.people().size();
    60	            due = due.add(figures.dueTotal());
    61	            overdue = overdue.add(figures.overdueTotal());
    62	        }
    63	        Rollup.Snapshot own = rollup.snapshot(sheetId);
    64	        return new Descendants(new ArrayList<>(found), peopleCount, text(due), text(overdue), own.people().size(),
    65	                text(own.dueTotal()), text(own.overdueTotal()));
    66	    }
