    68	    private Set<String> descendantsNow(String sheetId) {
    69	        Set<String> found = new LinkedHashSet<>();
    70	        Deque<String> next = new ArrayDeque<>(List.of(sheetId));
    71	        while (!next.isEmpty()) {
    72	            for (SheetParentLink child : parents.findByParentId(next.pop())) {
    73	                if (!child.getSheetId().equals(sheetId) && found.add(child.getSheetId())) next.add(child.getSheetId());
    74	            }
    75	        }
    76	        return found;
    77	    }
    78	
    79	    /** Each sheet naming a sheet of the tree as its parent is put back to the date, and is a descendant
    80	     *  when, as it stood then, it named that sheet. */
    81	    private Set<String> descendantsAsOf(String sheetId, LocalDate asOf) {
    82	        Set<String> found = new LinkedHashSet<>();
    83	        Set<String> restored = new LinkedHashSet<>(List.of(sheetId));
    84	        Deque<String> next = new ArrayDeque<>(List.of(sheetId));
    85	        while (!next.isEmpty()) {
    86	            String parent = next.pop();
    87	            for (String child : history.childrenOf(parent)) {
    88	                if (found.contains(child) || child.equals(sheetId)) continue;
    89	                if (restored.add(child)) history.restoreWithParents(child, asOf);
    90	                if (history.namesParent(child, parent)) {
    91	                    found.add(child);
    92	                    next.add(child);
    93	                }
    94	            }
    95	        }
    96	        // The store was put back beneath the persistence context: what it holds is read afresh.
    97	        entityManager.clear();
    98	        return found;
    99	    }
