    13	/**
    14	 * The as-of date a user's screen is set to: the screen sends it in a request header with every
    15	 * request while it is set. It belongs to that screen only; the store keeps nothing of it.
    16	 */
    17	public final class AsOf {
    18	
    19	    /** The request header carrying the screen's as-of date (yyyy-mm-dd). */
    20	    public static final String HEADER = "X-As-Of";
    21	
    22	    private AsOf() {
    23	    }
    24	
    25	    /** The as-of date the request was sent with, if any. */
    26	    public static Optional<LocalDate> of(HttpServletRequest request) {
    27	        String header = request.getHeader(HEADER);
    28	        if (header == null || header.isBlank()) return Optional.empty();
    29	        try {
    30	            return Optional.of(LocalDate.parse(header.trim()));
    31	        } catch (DateTimeParseException e) {
    32	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The as-of date is not a date.");
    33	        }
    34	    }
    35	
    36	    /** The id of the sheet a request is on, if it is on one. */
    37	    public static Optional<String> sheetOf(HttpServletRequest request) {
    38	        String path = request.getRequestURI().substring(request.getContextPath().length());
    39	        if (!path.startsWith(ViewerGuard.SHEETS)) return Optional.empty();
    40	        String rest = path.substring(ViewerGuard.SHEETS.length());
    41	        int slash = rest.indexOf('/');
    42	        if (slash < 0) return Optional.empty();
    43	        String id = URLDecoder.decode(rest.substring(0, slash), StandardCharsets.UTF_8).trim();
    44	        return id.isEmpty() ? Optional.empty() : Optional.of(id);
    45	    }
    46	
    47	    /** Whether a request only reads its sheet: a GET, or loading the sheet. */
    48	    public static boolean reads(HttpServletRequest request) {
    49	        String path = request.getRequestURI();
    50	        return "GET".equals(request.getMethod()) || "HEAD".equals(request.getMethod())
    51	                || ("POST".equals(request.getMethod()) && path.endsWith("/load"));
    52	    }
