    18	
    19	/**
    20	 * Serves a read from a screen set to an as-of date from the sheet as it stood then: the read runs
    21	 * in one transaction that first puts the sheet back to what {@link SheetHistory} kept for that date
    22	 * (with the as-of date as its today) and is always rolled back, so the store and the audit file are
    23	 * left as they were. Every other request on a sheet is marked as a change of it, so each of its
    24	 * commits is kept in the sheet's history. Putting a sheet back rewrites its rows until the rollback, so
    25	 * a read as of a date runs on its own: never alongside a change, which would deadlock with it on those rows.
    26	 */
    27	@Component
    28	public class AsOfFilter extends OncePerRequestFilter {
    29	
    30	    private final SheetHistory history;
    31	    private final TransactionTemplate transactions;
    32	    /** Changes share it; a read as of a date holds it alone. */
    33	    private final ReentrantReadWriteLock asOfReads = new ReentrantReadWriteLock(true);
    34	
    35	    public AsOfFilter(SheetHistory history, PlatformTransactionManager transactionManager) {
    36	        this.history = history;
    37	        this.transactions = new TransactionTemplate(transactionManager);
    38	    }
    39	
    40	    @Override
    41	    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
    42	            throws ServletException, IOException {
    43	        Optional<String> sheet = AsOf.sheetOf(request);
    44	        if (sheet.isEmpty()) {
    45	            chain.doFilter(request, response);
    46	            return;
    47	        }
    48	        Optional<LocalDate> asOf;
    49	        try {
    50	            asOf = AsOf.of(request);
    51	        } catch (ResponseStatusException e) {
    52	            response.sendError(e.getStatusCode().value(), e.getReason());
    53	            return;
    54	        }
    55	        if (asOf.isPresent() && AsOf.reads(request)) {
    56	            Lock alone = asOfReads.writeLock();
    57	            alone.lock();
    58	            try {
    59	                readAsOf(sheet.get(), asOf.get(), request, response, chain);
    60	            } finally {
    61	                alone.unlock();
    62	            }
    63	        } else if (asOf.isEmpty() && !AsOf.reads(request)) {
    64	            Lock shared = asOfReads.readLock();
    65	            shared.lock();
    66	            try {
    67	                history.changing(sheet.get(), () -> chain.doFilter(request, response));
    68	            } finally {
    69	                shared.unlock();
    70	            }
    71	        } else {
    72	            chain.doFilter(request, response);
    73	        }
    74	    }
    75	
    76	    private void readAsOf(String sheet, LocalDate asOf, HttpServletRequest request, HttpServletResponse response,
    77	            FilterChain chain) throws ServletException, IOException {
    78	        try {
    79	            transactions.executeWithoutResult((status) -> {
    80	                status.setRollbackOnly();
    81	                history.restoreWithParents(sheet, asOf);
    82	                try {
    83	                    chain.doFilter(request, response);
    84	                } catch (IOException e) {
    85	                    throw new UncheckedIOException(e);
    86	                } catch (ServletException e) {
    87	                    throw new WrappedServletException(e);
    88	                }
    89	            });
    90	        } catch (UncheckedIOException e) {
    91	            throw e.getCause();
    92	        } catch (WrappedServletException e) {
    93	            throw (ServletException) e.getCause();
    94	        }
    95	    }
    96	
    97	    private static final class WrappedServletException extends RuntimeException {
    98	        WrappedServletException(ServletException cause) {
    99	            super(cause);
   100	        }
   101	    }
   102	}
