    10	/**
    11	 * The app's transaction manager: as {@link JpaTransactionManager}, and just before a transaction
    12	 * made by a request that changes a sheet commits, it keeps what the sheet then holds in the sheet's
    13	 * history (see {@link SheetHistory}), in the same transaction, so what is kept is exactly what
    14	 * commits.
    15	 */
    16	public class HistoryTransactionManager extends JpaTransactionManager {
    17	
    18	    private final transient ObjectProvider<SheetHistory> history;
    19	
    20	    public HistoryTransactionManager(EntityManagerFactory entityManagerFactory, ObjectProvider<SheetHistory> history) {
    21	        super(entityManagerFactory);
    22	        this.history = history;
    23	    }
    24	
    25	    @Override
    26	    protected void prepareForCommit(DefaultTransactionStatus status) {
    27	        super.prepareForCommit(status);
    28	        if (!status.isNewTransaction() || status.isReadOnly()) return;
    29	        SheetHistory.changingSheet().ifPresent((sheet) -> {
    30	            EntityManagerHolder holder = (EntityManagerHolder) TransactionSynchronizationManager
    31	                    .getResource(obtainEntityManagerFactory());
    32	            if (holder != null) holder.getEntityManager().flush();
    33	            history.getObject().keep(sheet);
    34	        });
    35	    }
    36	}

