 60	    private static final Set<String> NOT_KEPT = Set.of("SHEET_HISTORY", "FLYWAY_SCHEMA_HISTORY");
 61	
 62	    /** The rows of one table, as kept. */
 63	    private record Rows(String table, String[] columns, List<Object[]> rows) implements Serializable {
 64	    }
