 66	    /** A sheet a request changes, and the sheet's today when the request began; none for a new sheet. */
 67	    private record Changing(String sheet, LocalDate madeOn) {
 68	    }
 69	
 70	    /** A table that belongs to a sheet: the condition that picks a sheet's rows from it. */
 71	    private record Table(String name, List<String> columns, String ofSheet) {
 72	    }
