 77	    public SheetHistory(DataSource dataSource) {
 78	        this.jdbc = new JdbcTemplate(dataSource);
 79	    }
 80	
 81	    /** Run the body as a change of the sheet: each commit it makes is kept in the sheet's history,
 82	     *  against the sheet's today as the body begins. */
 83	    public void changing(String sheet, Body body) throws IOException, ServletException {
 84	        Changing was = CHANGING.get();
 85	        CHANGING.set(new Changing(sheet, todayOf(sheet)));
 86	        try {
 87	            body.run();
 88	        } finally {
 89	            if (was == null) CHANGING.remove();
 90	            else CHANGING.set(was);
 91	        }
 92	    }
