 99	    /** Keep what the sheet holds now against the today the change was made on; within the transaction
100	     *  about to commit. A sheet the request made is kept against its today now. */
101	    public void keep(String sheet) {
102	        LocalDate now = todayOf(sheet);
103	        if (now == null) return;
104	        Changing changing = CHANGING.get();
105	        LocalDate madeOn = changing != null && changing.sheet().equals(sheet) && changing.madeOn() != null
106	                ? changing.madeOn() : now;
107	        byte[] data = serialize(capture(sheet));
108	        List<byte[]> last = jdbc.queryForList(
109	                "SELECT rows_data FROM sheet_history WHERE sheet_id = ? ORDER BY seq DESC LIMIT 1", byte[].class, sheet);
110	        if (!last.isEmpty() && Arrays.equals(last.get(0), data)) return;
111	        jdbc.update("MERGE INTO sheet_history (sheet_id, today, seq, rows_data) KEY (sheet_id, today) "
112	                + "VALUES (?, ?, NEXT VALUE FOR sheet_history_seq, ?)", sheet, madeOn, data);
113	    }
