132	    /** Put the sheet back to how it stood at the end of the date (see {@link #restore}), and with it each of
133	     *  the parents it names now, up to {@link SettingService#PARENT_LEVELS} levels up, whose rates it falls
134	     *  back on, then, for a cloned sheet, the sheet it was cloned from and so on up its parents and source. A parent kept nothing on a today on or before the date (its today runs apart from the
135	     *  sheet's) is put back to what it held when what the sheet is put back to was kept. Only for a
136	     *  transaction that is rolled back afterwards. */
137	    public void restoreWithParents(String sheet, LocalDate asOf) {
138	        List<String> parents = new ArrayList<>();
139	        for (String from = sheet; from != null; from = sourceOf(from)) {
140	            if (!from.equals(sheet)) {
141	                if (parents.contains(from)) break;
142	                parents.add(from);
143	            }
144	            String at = from;
145	            for (int level = 0; level < SettingService.PARENT_LEVELS; level++) {
146	                List<String> parent = jdbc.queryForList("SELECT parent_id FROM sheet_parent WHERE child_id = ?",
147	                        String.class, at);
148	                if (parent.isEmpty() || parent.get(0).equals(sheet) || parents.contains(parent.get(0))) break;
149	                at = parent.get(0);
