178	     * last change made on a today on or before it left, or an empty sheet when there was none. Only
179	     * for a transaction that is rolled back afterwards.
180	     */
181	    public void restore(String sheet, LocalDate asOf) {
182	        put(sheet, asOf, jdbc.queryForList(
183	                "SELECT rows_data FROM sheet_history WHERE sheet_id = ? AND today <= ? ORDER BY seq DESC LIMIT 1",
184	                byte[].class, sheet, asOf));
185	    }
