187	    /** Put the sheet back to what it kept last up to the sequence, with the date as its today, or an empty
188	     *  sheet when it kept nothing by then. Only for a transaction that is rolled back afterwards. */
189	    private void restoreAsKeptBy(String sheet, long seq, LocalDate asOf) {
190	        put(sheet, asOf, jdbc.queryForList(
191	                "SELECT rows_data FROM sheet_history WHERE sheet_id = ? AND seq <= ? ORDER BY seq DESC LIMIT 1",
192	                byte[].class, sheet, seq));
193	    }
194	
195	    /** Replace the sheet's rows with those kept (none: an empty sheet), with the date as its today. */
196	    private void put(String sheet, LocalDate asOf, List<byte[]> kept) {
197	        List<Table> all = tables();
198	        for (int i = all.size() - 1; i >= 0; i--) {
199	            Table table = all.get(i);
200	            jdbc.update("DELETE FROM " + table.name() + " WHERE " + table.ofSheet(), sheet);
201	        }
202	        if (kept.isEmpty()) {
203	            jdbc.update("INSERT INTO sheet (id, created_at, today) VALUES (?, CURRENT_TIMESTAMP, ?)", sheet, asOf);
204	            return;
205	        }
206	        Map<String, Rows> rows = deserialize(kept.get(0)).stream()
207	                .collect(Collectors.toMap(Rows::table, (r) -> r));
208	        for (Table table : all) {
209	            Rows these = rows.get(table.name());
210	            if (these == null || these.rows().isEmpty()) continue;
211	            String insert = "INSERT INTO " + table.name() + " (" + String.join(", ", these.columns()) + ") VALUES ("
212	                    + String.join(", ", java.util.Collections.nCopies(these.columns().length, "?")) + ")";
213	            jdbc.batchUpdate(insert, these.rows());
214	        }
215	        if (jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", asOf, sheet) == 0) {
216	            jdbc.update("INSERT INTO sheet (id, created_at, today) VALUES (?, CURRENT_TIMESTAMP, ?)", sheet, asOf);
217	        }
218	    }
