220	    private List<Rows> capture(String sheet) {
221	        List<Rows> all = new ArrayList<>();
222	        for (Table table : tables()) {
223	            String columns = String.join(", ", table.columns());
224	            String order = java.util.stream.IntStream.rangeClosed(1, table.columns().size())
225	                    .mapToObj(Integer::toString).collect(Collectors.joining(", "));
226	            List<Object[]> rows = jdbc.query("SELECT " + columns + " FROM " + table.name() + " WHERE "
227	                    + table.ofSheet() + " ORDER BY " + order, (rs, n) -> {
228	                        Object[] row = new Object[table.columns().size()];
229	                        for (int c = 0; c < row.length; c++) row[c] = rs.getObject(c + 1);
230	                        return row;
231	                    }, sheet);
232	            all.add(new Rows(table.name(), table.columns().toArray(String[]::new), rows));
233	        }
