237	    /** The tables that belong to a sheet, each after the tables its rows reference. */
238	    private List<Table> tables() {
239	        List<Table> found = tables;
240	        if (found == null) {
241	            found = jdbc.execute((java.sql.Connection connection) -> discover(connection.getMetaData()));
242	            tables = found;
243	        }
