    18	
    19	    /** An amount as the claim form takes it: up to two decimals. */
    20	    private static final Pattern AMOUNT = Pattern.compile("-?\\d{1,10}(\\.\\d{1,2})?");
    21	
    22	    private final ClaimTemplateRepository templates;
    23	    private final ClaimService claims;
    24	    private final SheetService sheets;
