    28	    public ClaimTemplateService(ClaimTemplateRepository templates, ClaimService claims, SheetService sheets,
    29	            SheetRepository sheetRows, Audit audit) {
    30	        this.templates = templates;
    31	        this.claims = claims;
    32	        this.sheets = sheets;
    33	        this.sheetRows = sheetRows;
    34	        this.audit = audit;
    35	    }
    36	
    37	    /** The sheet's claim templates by name. */
    38	    @Transactional(readOnly = true)
    39	    public List<ClaimTemplate> list(String sheetId) {
    40	        return templates.findBySheetIdOrderByNameAsc(sheetId);
    41	    }
    42	
    43	    /** Save a template under its name (trimmed), replacing the one of that name. Refused for a blank
    44	     *  name and for an amount the claim form would refuse: not a number of up to two decimals, or
    45	     *  negative (a correction, which a template cannot name the claim it corrects for). */
    46	    @Transactional
    47	    public ClaimTemplate save(String sheetId, String user, String name, String amount, String note) {
    48	        String key = name == null ? "" : name.trim();
    49	        if (key.isEmpty()) {
    50	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Type a template name.");
    51	        }
    52	        String typed = amount == null ? "" : amount.trim();
    53	        if (!AMOUNT.matcher(typed).matches() || new BigDecimal(typed).signum() < 0) {
    54	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
    55	                    "Type an amount of zero or more with up to two decimals.");
    56	        }
